mapper.select:
select count(*)
from user_file
where user_id = #{userId}
  and parent_id = #{targetId}
  and file_name = (select uf.file_name from user_file uf where id = #{id});

with recursive tree as (select t1.id, t1.is_directory, t1.object_id from user_file t1 where id in
#{id}
union all select t2.id, t2.is_directory, t2.object_id from tree t1 inner join user_file t2 on t1.id = t2.parent_id # where t2.media_category != 0 ) select object_id, id, is_directory from tree where is_directory != 1;

select count(*) from user_file
where user_id = #{userId}
and parent_id = #{parentId}
and deleted = 0
and file_name like concat(#{originalFileName}, '%')

with recursive tree as (select uf.id, uf.parent_id, uf.file_size from user_file uf where uf.id in
#{id}
and uf.deleted = 0 union all select uf.id, uf.parent_id, uf.file_size from tree t inner join user_file uf on t.id = uf.parent_id where uf.deleted = 0) select sum(tree.file_size) from tree;

with recursive tree as (select uf.* from user_file uf where uf.user_id = #{userId} and uf.deleted = 0 and uf.parent_id in
#{parentId}
union all select uf.* from tree t inner join user_file uf on t.id = uf.parent_id and t.user_id = uf.user_id and uf.deleted = 0) select tree.* from tree;
